DELETE FROM s_height1518 WHERE id=@id AND b_year=(@b_year+543);
INSERT IGNORE INTO s_height1518
(
SELECT
	 @id,h.hoscode hospcode,concat(h.provcode,h.distcode,h.subdistcode,SUBSTR(CONCAT('00',h.mu),-2)) as areacode
   ,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543 as b_year
,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(10,11,12,1,2) , CONCAT(n.HOSPCODE,'-',n.PID),NULL)) B1Q1
,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(5,6,7), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) B1Q2
,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(10,11,12,1,2) AND nutri2 in(3,4,5) AND nutri3 in(3), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A1Q1
,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(5,6,7,8,9) AND nutri2 in(3,4,5) AND nutri3 in(3), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A1Q2

,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(10,11,12,1,2)  AND nutri3 in(1), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A2Q1
,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(5,6,7,8,9) AND nutri3 in(1), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A2Q2

,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(10,11,12,1,2)  AND nutri3 IN(5,6,7), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A3Q1
,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(5,6,7,8,9) AND nutri3 IN(5,6,7), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A3Q2

,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(10,11,12,1,2)  AND nutri2 in(1), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A4Q1
,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(5,6,7,8,9) AND nutri2 in(1), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A4Q2

,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(10,11,12,1,2) AND sex in(1) AND TIMESTAMPDIFF(year,birth,date_serv) in(18)  ,  CONCAT(n.HOSPCODE,'-',n.PID,'-',n.quarter_m),NULL)) B3Q1
,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(5,6,7,8,9) AND sex in(1) AND TIMESTAMPDIFF(year,birth,date_serv) in(18),  CONCAT(n.HOSPCODE,'-',n.PID,'-',n.quarter_m),NULL)) B3Q2
,SUM(if(DATE_FORMAT(n.date_serv,'%m') IN(10,11,12,1,2) AND sex in(1) AND TIMESTAMPDIFF(year,birth,date_serv) in(18),height,0 )) A5Q1
,SUM(if(DATE_FORMAT(n.date_serv,'%m') IN(5,6,7,8,9) AND sex in(1) AND TIMESTAMPDIFF(year,birth,date_serv) in(18),height,0 )) A5Q2

,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(10,11,12,1,2) AND sex in(2) AND TIMESTAMPDIFF(year,birth,date_serv) in(18) ,  CONCAT(n.HOSPCODE,'-',n.PID,'-',n.quarter_m),NULL)) B4Q1
,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(5,6,7,8,9) AND sex in(2) AND TIMESTAMPDIFF(year,birth,date_serv) in(18),  CONCAT(n.HOSPCODE,'-',n.PID,'-',n.quarter_m),NULL)) B4Q2
,SUM(if(DATE_FORMAT(n.date_serv,'%m') IN(10,11,12,1,2) AND sex in(2) AND TIMESTAMPDIFF(year,birth,date_serv) in(18),height,0 )) A6Q1
,SUM(if(DATE_FORMAT(n.date_serv,'%m') IN(5,6,7,8,9) AND sex in(2) AND TIMESTAMPDIFF(year,birth,date_serv) in(18),height,0 )) A6Q2
/*xx*/
,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(10,11,12,1,2)  AND nutri3 in(2), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A7Q1
,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(5,6,7,8,9) AND nutri3 in(2), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A7Q2

,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(10,11,12,1,2)  AND nutri3 in(3), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A8Q1
,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(5,6,7,8,9) AND nutri3 in(3), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A8Q2

,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(10,11,12,1,2)  AND nutri3 in(4), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A9Q1
,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(5,6,7,8,9) AND nutri3 in(4), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A9Q2

,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(10,11,12,1,2)  AND nutri3 in(5), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A10Q1
,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(5,6,7,8,9) AND nutri3 in(5), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A10Q2

,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(10,11,12,1,2)  AND nutri3 in(6), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A11Q1
,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(5,6,7,8,9) AND nutri3 in(6), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A11Q2

,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(10,11,12,1,2)  AND nutri2 in(2), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A12Q1
,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(5,6,7,8,9) AND nutri2 in(2), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A12Q2

,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(10,11,12,1,2)  AND nutri2 in(3,4,5), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A13Q1
,COUNT(DISTINCT if(DATE_FORMAT(n.date_serv,'%m') IN(5,6,7,8,9) AND nutri2 in(3,4,5), CONCAT(n.HOSPCODE,'-',n.PID),NULL)) A13Q2
FROM
t_nutrition_service n inner join chospital h on n.hospcode=h.hoscode
WHERE h.provcode in(@prov_c)   AND TIMESTAMPDIFF(YEAR,n.birth,n.DATE_SERV) BETWEEN 15 AND 18
GROUP BY n.hospcode

);
